package moe.crx.overport.pfdmr;
import java.nio.*;import java.nio.file.*;import java.util.*;import java.io.*;import com.reandroid.json.*;import moe.crx.overport.patching.*;import com.reandroid.apk.ApkModule;import com.reandroid.archive.FileInputSource;import com.android.apksig.*;
public class RedMatterSignerTests {
 static int n;static void check(boolean ok,String s){if(!ok)throw new AssertionError(s);System.out.println("PASS "+s);n++;}
 interface Action{void run()throws Exception;}static void rejected(Action fn,String s)throws Exception{try{fn.run();}catch(IllegalStateException expected){check(true,s);return;}throw new AssertionError(s);}
 static byte[] fixture(){byte[] bytes=new byte[8192];ByteBuffer b=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);b.putInt(0,0x464c457f);b.put(4,(byte)2);b.put(5,(byte)1);b.putShort(18,(short)183);b.putLong(32,64);b.putShort(54,(short)56);b.putShort(56,(short)1);b.putInt(64,1);b.putLong(72,256);b.putLong(80,0x6b8c000L);b.putLong(96,4096);int at=256+0x428;b.putInt(at,RedMatterSignerPatch.low(RedMatterSignerPatch.EXPECTED));b.putInt(at+4,RedMatterSignerPatch.high(RedMatterSignerPatch.EXPECTED));b.putInt(at+8,0x6b08001f);b.putInt(at+12,0x54000040);return bytes;}
 static JSONObject installSyntheticReceipt(Path ws,byte[] original,byte[] cert)throws Exception{
  int at=RedMatterSignerPatch.offset(original,RedMatterSignerPatch.SITE);byte[] updated=RedMatterSignerPatch.edit(original,Arrays.hashCode(cert),StereoPatch.sha256(original));JSONObject r=new JSONObject().put("version",1).put("profile",RedMatterSignerPatch.ID).put("before_sha256",RedMatterSignerPatch.ORIGINAL).put("after_sha256",StereoPatch.sha256(updated)).put("offset",at).put("original_bytes",Base64.getEncoder().encodeToString(Arrays.copyOfRange(original,at,at+8))).put("certificate_sha256",StereoPatch.sha256(cert)).put("signature_hash",Arrays.hashCode(cert));Path game=ws.resolve(RedMatterSignerPatch.GAME),receipt=ws.resolve(RedMatterSignerPatch.RECEIPT);Files.createDirectories(game.getParent());Files.createDirectories(receipt.getParent());Files.write(game,updated);Files.writeString(receipt,r.toString());return r;
 }
 static byte[] certificate(Path apk)throws Exception{var result=new ApkVerifier.Builder(apk.toFile()).build().verify();check(result.isVerified(),"output APK signature valid");return result.getSignerCertificates().get(0).getEncoded();}
 public static void main(String[] args)throws Exception{
  Path run=Path.of(args[0]);Files.createDirectories(run);byte[] raw=fixture(),der={-1,-128,0,127};int hash=Arrays.hashCode(der),at=RedMatterSignerPatch.offset(raw,RedMatterSignerPatch.SITE);byte[] edited=RedMatterSignerPatch.edit(raw,hash,StereoPatch.sha256(raw));
  byte[] golden=RedMatterSignerPatch.edit(raw,0xb84aca10,StereoPatch.sha256(raw));ByteBuffer goldenWords=ByteBuffer.wrap(golden).order(ByteOrder.LITTLE_ENDIAN);check(goldenWords.getInt(at)==0x52994208&&goldenWords.getInt(at+4)==0x72b70948,"matches contributor's independently recorded instruction bytes");
  check(at==1320,"PT_LOAD maps comparison VA to different file offset");check(hash==770849,"Android signed-byte certificate hash semantics");ByteBuffer b=ByteBuffer.wrap(edited).order(ByteOrder.LITTLE_ENDIAN);check(b.getInt(at)==RedMatterSignerPatch.low(hash)&&b.getInt(at+4)==RedMatterSignerPatch.high(hash),"both signer immediate halves encoded");boolean same=true;for(int i=0;i<raw.length;i++)if(i<at||i>=at+8)if(raw[i]!=edited[i])same=false;check(same,"comparison, branch and every unrelated byte preserved");
  rejected(()->RedMatterSignerPatch.edit(raw,1,RedMatterSignerPatch.ORIGINAL),"unknown original build rejected");byte[] arch=raw.clone();arch[18]=0;rejected(()->RedMatterSignerPatch.edit(arch,1,StereoPatch.sha256(arch)),"wrong architecture rejected");byte[] pattern=raw.clone();pattern[at+8]^=1;rejected(()->RedMatterSignerPatch.edit(pattern,1,StereoPatch.sha256(pattern)),"changed comparison rejected");
  JSONObject r=new JSONObject().put("after_sha256",StereoPatch.sha256(edited)).put("offset",at).put("original_bytes",Base64.getEncoder().encodeToString(Arrays.copyOfRange(raw,at,at+8)));
  check(Arrays.equals(raw,RedMatterSignerPatch.restored(edited,r,StereoPatch.sha256(raw))),"exact engine rollback");byte[] tampered=edited.clone();tampered[400]^=1;rejected(()->RedMatterSignerPatch.restored(tampered,r,StereoPatch.sha256(raw)),"tampered output blocks rollback");byte[] restored=RedMatterSignerPatch.restored(edited,r,StereoPatch.sha256(raw));check(Arrays.equals(edited,RedMatterSignerPatch.edit(restored,hash,StereoPatch.sha256(raw))),"same-key restore and reapply stable");check(!Arrays.equals(edited,RedMatterSignerPatch.edit(restored,12345,StereoPatch.sha256(raw))),"different-key rebuild changes target");
  Path engine=run.resolve("fixture.so");Files.write(engine,raw);Path unsigned=run.resolve("fixture-unsigned.apk");try(var apk=ApkModule.loadApkFile(new File(args[1]))){apk.getAndroidManifest().setPackageName("com.VerticalRobot.RedMatter");apk.getAndroidManifest().setVersionCode(38);apk.getAndroidManifest().setVersionName("1.0.013");apk.refreshManifest();apk.keepManifestChanges();apk.add(new FileInputSource(engine.toFile(),"lib/arm64-v8a/libUE4.so"));apk.writeApk(unsigned.toFile());}
  var c=new PatcherContext("3.4.3-aa54c3f",run.resolve("cache").toFile(),"RedMatter.apk","{filename}.{ext}");try(var in=Files.newInputStream(unsigned)){c.prepare(in);}Path signed=run.resolve("fixture-signed.apk");c.exportAndClose(Files.newOutputStream(signed));c.cleanup();try(var in=Files.newInputStream(signed)){c.prepare(in);}
  RedMatterSignerPatch.validateSelection(c,Map.of(RedMatterSignerPatch.ID,List.of()));check(true,"exact package/version and valid single-signer input accepted");
  rejected(()->c.patch(Map.of(RedMatterSignerPatch.ID,List.of()),(i,p)->kotlin.Unit.INSTANCE),"full conversion rejects unrecognized engine despite matching package");
  byte[] certA=c.outputSignerCertificate();Path ws=c.getWorkingDir().toPath();JSONObject record=installSyntheticReceipt(ws,raw,certA);
  Path otherKey=run.resolve("other.keystore");var other=SignatureStore.INSTANCE.getSignature(otherKey.toFile());byte[] certB=other.getCertificates().get(0).getEncoded();check(!Arrays.equals(certA,certB),"independent signer fixture created");Files.copy(otherKey,run.resolve("cache/signatures/com.VerticalRobot.RedMatter.keystore"),StandardCopyOption.REPLACE_EXISTING);
  Path output=run.resolve("pinned-output.apk");c.exportAndClose(Files.newOutputStream(output));check(Arrays.equals(certificate(output),certA),"export reuses pinned signer even if keystore changes after patch");RedMatterSignerPatch.verifyOutput(ws,output,certA);check(true,"final engine constant and actual APK certificate agree");rejected(()->RedMatterSignerPatch.verifyOutput(ws,output,certB),"wrong final signer rejected");
  installSyntheticReceipt(ws,raw,certB);ByteArrayOutputStream sink=new ByteArrayOutputStream();rejected(()->c.export(sink),"export fails before returning APK when profile targets different key");check(sink.size()==0,"mismatched signed APK not returned to caller");c.cleanup();try(var in=Files.newInputStream(signed)){c.prepare(in);}check(Arrays.equals(c.outputSignerCertificate(),certB),"new input clears signer pin and selects current key");
  var keyA=SignatureStore.INSTANCE.getSignature(run.resolve("key-a.keystore").toFile());Path multi=run.resolve("multi.apk");new ApkSigner.Builder(List.of(keyA,other)).setInputApk(unsigned.toFile()).setOutputApk(multi.toFile()).setMinSdkVersion(29).setV3SigningEnabled(false).setV4SigningEnabled(false).build().sign();var validMulti=new ApkVerifier.Builder(multi.toFile()).build().verify();check(validMulti.isVerified()&&validMulti.getSignerCertificates().size()==2,"multi-signer fixture has a valid cryptographic signature");c.cleanup();try(var in=Files.newInputStream(multi)){c.prepare(in);}rejected(()->RedMatterSignerPatch.validateSelection(c,Map.of(RedMatterSignerPatch.ID,List.of())),"multi-signer source rejected");c.cleanup();
  check(ClimbStabilityPatch.expand(Map.of(RedMatterSignerPatch.ID,List.of())).containsKey(MossResolutionPatch.ID),"Red Matter profile includes resolution");
  check(!PatchStore.INSTANCE.get(RedMatterSignerPatch.ID).isRecommended()&&!PatchStore.INSTANCE.get(ClimbStabilityPatch.ID).isRecommended(),"both new switches off by default");
  System.out.println("ALL "+n+" RED MATTER SIGNER CHECKS PASSED (synthetic engine; real package hash remains guarded)");
 }
}
